// Further reading for the camera library: bibliographic citations (book,
// author, edition, year, pages) from the owner's cinematic-atlas, per
// technique, coverage pattern and cut rule. Citations only; the books stay in
// the atlas. When the owner runs the atlas and sets its URL, each page links
// to `<atlas URL>#/book/<id>/<page>`. data.js is generated by tools/atlas-refs.mjs.
import { REFERENCE_BOOKS, REFERENCES } from "./data.js";

const BOOKS = new Map(REFERENCE_BOOKS.map((book) => [book.id, book]));
const ATLAS_URL_KEY = "cozyclay.atlasUrl";

/** "Steven D. Katz, Film Directing: Shot by Shot (25th anniversary edition, 2019)". */
function bookCitation(book) {
	const tail = [book.edition, book.year].filter(Boolean).join(", ");
	return `${book.author}, ${book.title}${tail ? ` (${tail})` : ""}`;
}

/** The citations for one entry; section is "techniques", "patterns" or "cuts". [] when the atlas has none. */
export function referencesFor(section, id) {
	return (REFERENCES[section]?.[id] ?? []).filter((ref) => BOOKS.has(ref.book)).map((ref) => {
		const book = BOOKS.get(ref.book);
		return { book: book.id, title: book.title, author: book.author, edition: book.edition, year: book.year, pages: [...ref.pages],
			cite: `${bookCitation(book)}, p. ${ref.pages.join(", ")}` };
	});
}

/** Every entry's citations in one compact read for agents (list_camera_techniques { references: true }). */
export function referenceDigest() {
	const rows = (section) => Object.entries(REFERENCES[section]).map(([id, refs]) => `${id}: ${refs.map((ref) => `${ref.book} p. ${ref.pages.join(", ")}`).join("; ")}`);
	return {
		books: REFERENCE_BOOKS.map((book) => `${book.id} = ${bookCitation(book)}`),
		techniques: rows("techniques"), patterns: rows("patterns"), cuts: rows("cuts"),
	};
}

/** An http(s) atlas address with its path kept and its query and hash dropped, ending in "/"; null otherwise. */
export function normalizeAtlasUrl(value) {
	let url;
	try { url = new URL(String(value ?? "").trim()); } catch { return null; }
	if (url.protocol !== "http:" && url.protocol !== "https:") return null;
	url.search = ""; url.hash = "";
	return url.href.endsWith("/") ? url.href : `${url.href}/`;
}

/** The atlas URL this browser remembers (a per-viewer setting), or null. */
export function readAtlasUrl(storage = globalThis.localStorage) {
	try { return normalizeAtlasUrl(storage?.getItem(ATLAS_URL_KEY)); } catch { return null; }
}

/** Remembers a valid atlas URL, forgets it when blank or invalid; returns what is stored. */
export function writeAtlasUrl(value, storage = globalThis.localStorage) {
	const url = normalizeAtlasUrl(value);
	try { if (url) storage?.setItem(ATLAS_URL_KEY, url); else storage?.removeItem(ATLAS_URL_KEY); } catch { /* storage blocked: the setting lasts this session only */ }
	return url;
}

/** `<atlas URL>#/book/<id>/<page>`, the atlas reader's own route. */
export const atlasPageHref = (atlasUrl, book, page) => `${atlasUrl}#/book/${encodeURIComponent(book)}/${page}`;
